{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE or replace table snitch_db.maplemonk.mdq_v1 as WITH sales AS ( SELECT s.BRANCH_CODE, s.MARKETPLACE_MAPPED, CASE WHEN LOWER(c.STYLE) LIKE \'%core%\' THEN \'Core\' ELSE \'Fashion\' END AS STYLE_TYPE, s.SUBORDER_QUANTITY, DATEDIFF(day, DATEADD(MONTH, -2, CURRENT_DATE()), s.ORDER_DATE) AS offset FROM snitch_db.maplemonk.STORE_FACT_ITEMS_OFFLINE s LEFT JOIN snitch_db.maplemonk.metafields_data c ON s.SKU_GROUP = c.SKU_GROUP WHERE s.ORDER_DATE >= DATEADD(MONTH, -2, CURRENT_DATE()) AND s.MARKETPLACE_MAPPED NOT LIKE \'%YELHANKA%\' AND s.MARKETPLACE_MAPPED NOT LIKE \'%EMIZA%\' AND c.CATEGORY NOT IN (\'Perfumes\', \'Shoes\', \'Sunglasses\', \'Belts\', \'Bags\') ), binned AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, STYLE_TYPE, SUBORDER_QUANTITY, CASE WHEN offset BETWEEN 45 AND 59 THEN \'W1\' WHEN offset BETWEEN 30 AND 44 THEN \'W2\' WHEN offset BETWEEN 15 AND 29 THEN \'W3\' WHEN offset BETWEEN 0 AND 14 THEN \'W4\' END AS WEEK FROM sales ), summary AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, STYLE_TYPE, SUM(CASE WHEN WEEK = \'W1\' THEN SUBORDER_QUANTITY ELSE 0 END) AS ROS_W1, SUM(CASE WHEN WEEK = \'W2\' THEN SUBORDER_QUANTITY ELSE 0 END) AS ROS_W2, SUM(CASE WHEN WEEK = \'W3\' THEN SUBORDER_QUANTITY ELSE 0 END) AS ROS_W3, SUM(CASE WHEN WEEK = \'W4\' THEN SUBORDER_QUANTITY ELSE 0 END) AS ROS_W4 FROM binned GROUP BY BRANCH_CODE, MARKETPLACE_MAPPED, STYLE_TYPE ), master_clean AS ( SELECT \"STORE CODE\" AS BRANCH_CODE, \"CLUSTER\" AS CLUSTER, \"CARPET AREA\" AS CARPET_AREA, \"VM OPTION CAPACITY\" AS VM_OPTION_CAPACITY, \"BASE STOCK\" AS BASE_STOCK, \"BOH %\" AS BOH_PCT FROM snitch_db.maplemonk.master_file ), base_output AS ( SELECT s.BRANCH_CODE, s.MARKETPLACE_MAPPED, m.CLUSTER, m.CARPET_AREA, m.VM_OPTION_CAPACITY, m.BASE_STOCK, m.BOH_PCT, CASE WHEN m.CARPET_AREA > 4000 THEN \'A\' WHEN m.CARPET_AREA BETWEEN 2500 AND 3999 THEN \'B\' ELSE \'C\' END AS STORE_SIZE_GROUP, s.STYLE_TYPE, GREATEST(s.ROS_W1, s.ROS_W2, s.ROS_W3, s.ROS_W4) AS MAX_ROS, ROUND(GREATEST(s.ROS_W1, s.ROS_W2, s.ROS_W3, s.ROS_W4) / 15.0, 2) AS DAILY_ROS, CASE WHEN s.STYLE_TYPE = \'Core\' AND m.CARPET_AREA > 4000 THEN ROUND(GREATEST(s.ROS_W1, s.ROS_W2, s.ROS_W3, s.ROS_W4) / 15.0 * 1.2, 2) WHEN s.STYLE_TYPE = \'Core\' THEN ROUND(GREATEST(s.ROS_W1, s.ROS_W2, s.ROS_W3, s.ROS_W4) / 15.0 * 1.25, 2) ELSE ROUND(GREATEST(s.ROS_W1, s.ROS_W2, s.ROS_W3, s.ROS_W4) / 15.0, 2) END AS ADJUSTED_DAILY_ROS, ROUND( m.VM_OPTION_CAPACITY * CASE WHEN s.STYLE_TYPE = \'Core\' AND m.CARPET_AREA > 4000 THEN 0.10 WHEN s.STYLE_TYPE = \'Core\' AND m.CARPET_AREA BETWEEN 2500 AND 3999 THEN 0.15 WHEN s.STYLE_TYPE = \'Core\' THEN 0.20 WHEN s.STYLE_TYPE = \'Fashion\' AND m.CARPET_AREA > 4000 THEN 0.90 WHEN s.STYLE_TYPE = \'Fashion\' AND m.CARPET_AREA BETWEEN 2500 AND 3999 THEN 0.85 ELSE 0.80 END ) AS ADJUSTED_OPTION_COUNT FROM summary s LEFT JOIN master_clean m ON s.BRANCH_CODE = m.BRANCH_CODE WHERE m.CLUSTER IS NOT NULL ), depth_solver AS ( SELECT core.BRANCH_CODE, core.MARKETPLACE_MAPPED, ROUND( CASE WHEN fashion.ADJUSTED_OPTION_COUNT + 1.5 * core.ADJUSTED_OPTION_COUNT = 0 THEN 0 ELSE core.BASE_STOCK / (fashion.ADJUSTED_OPTION_COUNT + 1.5 * core.ADJUSTED_OPTION_COUNT) END, 2 ) AS FASHION_DEPTH, ROUND( CASE WHEN fashion.ADJUSTED_OPTION_COUNT + 1.5 * core.ADJUSTED_OPTION_COUNT = 0 THEN 0 ELSE 1.5 * core.BASE_STOCK / (fashion.ADJUSTED_OPTION_COUNT + 1.5 * core.ADJUSTED_OPTION_COUNT) END, 2 ) AS CORE_DEPTH FROM ( SELECT * FROM base_output WHERE STYLE_TYPE = \'Core\' ) core JOIN ( SELECT * FROM base_output WHERE STYLE_TYPE = \'Fashion\' ) fashion ON core.BRANCH_CODE = fashion.BRANCH_CODE AND core.MARKETPLACE_MAPPED = fashion.MARKETPLACE_MAPPED ), final_with_totals AS ( SELECT out.*, ROUND( CASE WHEN out.STYLE_TYPE = \'Core\' THEN ds.CORE_DEPTH WHEN out.STYLE_TYPE = \'Fashion\' THEN ds.FASHION_DEPTH ELSE NULL END, 0 ) AS CALCULATED_DEPTH, ROUND( CASE WHEN out.STYLE_TYPE = \'Core\' THEN ds.CORE_DEPTH * out.ADJUSTED_OPTION_COUNT WHEN out.STYLE_TYPE = \'Fashion\' THEN ds.FASHION_DEPTH * out.ADJUSTED_OPTION_COUNT ELSE NULL END, 0 ) AS TOTAL_UNITS FROM base_output out LEFT JOIN depth_solver ds ON out.BRANCH_CODE = ds.BRANCH_CODE AND out.MARKETPLACE_MAPPED = ds.MARKETPLACE_MAPPED ) SELECT *, ROUND(100.0 * TOTAL_UNITS / NULLIF(SUM(TOTAL_UNITS) OVER (PARTITION BY BRANCH_CODE, MARKETPLACE_MAPPED), 0), 0) AS CORE_FASHION_STOCK_SHARE_PCT FROM final_with_totals ORDER BY BRANCH_CODE, CASE WHEN STYLE_TYPE = \'Core\' THEN 1 ELSE 2 END; Create or replace table snitch_db.maplemonk.Global_pareto_v2 AS WITH offline AS ( SELECT SKU_GROUP, NEW_CATEGORY, STYLE, DESIGNS, COLLAR_NEW, MATERIAL_NEW, SLEEVE_TYPE, FIT, COLOR, SKU_CLASS, COUNT(DISTINCT CLUSTER) AS cluster_count, LISTAGG(DISTINCT CLUSTER, \', \') AS clusters_list, SUM(INVENTORY + JIT_QTY) AS offline_inventory FROM snitch_db.maplemonk.offline_master WHERE COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) > 0 AND COALESCE(NEW_CATEGORY, \'\') NOT IN (\'Sunglasses\', \'Perfumes\', \'Belts\', \'Shoes\', \'Bags\', \'\') GROUP BY SKU_GROUP, NEW_CATEGORY, STYLE, DESIGNS, COLLAR_NEW, MATERIAL_NEW, SLEEVE_TYPE, FIT, COLOR, SKU_CLASS ), wh AS ( SELECT CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS SKU_GROUP, SUM(CASE WHEN TRIM(UPPER(SIZE)) IN (\'28\', \'XS\') THEN inventory ELSE 0 END) AS xs_units, SUM(CASE WHEN TRIM(UPPER(SIZE)) IN (\'30\', \'S\', \'3XL\') THEN inventory ELSE 0 END) AS s_units, SUM(CASE WHEN TRIM(UPPER(SIZE)) IN (\'32\', \'M\', \'4XL\') THEN inventory ELSE 0 END) AS m_units, SUM(CASE WHEN TRIM(UPPER(SIZE)) IN (\'34\', \'L\', \'5XL\') THEN inventory ELSE 0 END) AS l_units, SUM(CASE WHEN TRIM(UPPER(SIZE)) IN (\'36\', \'XL\', \'6XL\') THEN inventory ELSE 0 END) AS xl_units, SUM(inventory) AS wh_inventory FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = CURRENT_DATE AND facility IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\') GROUP BY SKU_GROUP ), sku_sales AS ( SELECT SKU_GROUP, SUM(SALES_LAST_30_DAYS) AS total_sales FROM snitch_db.maplemonk.offline_master WHERE SALES_LAST_30_DAYS IS NOT NULL AND COALESCE(NEW_CATEGORY, \'\') NOT IN (\'Sunglasses\', \'Perfumes\', \'Belts\', \'Shoes\', \'Bags\', \'\') GROUP BY SKU_GROUP ), ranked_sales AS ( SELECT *, 100 * DIV0(total_sales, SUM(total_sales) OVER ()) AS share FROM sku_sales ), pareto AS ( SELECT *, SUM(share) OVER ( ORDER BY share DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_share FROM ranked_sales ), pareto_tagged AS ( SELECT SKU_GROUP, total_sales, share, cumulative_share, CASE WHEN cumulative_share < 10 THEN \'10%\' WHEN cumulative_share < 20 THEN \'20%\' WHEN cumulative_share < 30 THEN \'30%\' WHEN cumulative_share < 40 THEN \'40%\' WHEN cumulative_share < 50 THEN \'50%\' WHEN cumulative_share < 60 THEN \'60%\' WHEN cumulative_share < 70 THEN \'70%\' WHEN cumulative_share < 80 THEN \'80%\' WHEN cumulative_share < 90 THEN \'90%\' ELSE \'100%\' END AS percentage_category FROM pareto ), all_clusters AS ( SELECT DISTINCT CLUSTER FROM snitch_db.maplemonk.offline_master ), cluster_sku_cross AS ( SELECT a.CLUSTER, o.SKU_GROUP FROM all_clusters a CROSS JOIN (SELECT DISTINCT SKU_GROUP FROM offline) o ), missing_clusters_raw AS ( SELECT cs.SKU_GROUP, cs.CLUSTER FROM cluster_sku_cross cs LEFT JOIN ( SELECT DISTINCT SKU_GROUP, CLUSTER FROM snitch_db.maplemonk.offline_master WHERE COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) > 0 ) inv ON cs.SKU_GROUP = inv.SKU_GROUP AND cs.CLUSTER = inv.CLUSTER WHERE inv.CLUSTER IS NULL ), missing_clusters_final AS ( SELECT SKU_GROUP, LISTAGG(CLUSTER, \', \') AS missing_clusters FROM missing_clusters_raw GROUP BY SKU_GROUP ), all_branch_codes AS ( SELECT DISTINCT BRANCH_CODE FROM snitch_db.maplemonk.offline_master ), sku_branch_cross AS ( SELECT s.SKU_GROUP, b.BRANCH_CODE FROM (SELECT DISTINCT SKU_GROUP FROM offline) s CROSS JOIN all_branch_codes b ), missing_branch_matrix AS ( SELECT sb.SKU_GROUP, sb.BRANCH_CODE FROM sku_branch_cross sb LEFT JOIN ( SELECT SKU_GROUP, BRANCH_CODE, SUM(COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0)) AS total_inv FROM snitch_db.maplemonk.offline_master GROUP BY SKU_GROUP, BRANCH_CODE ) inv ON sb.SKU_GROUP = inv.SKU_GROUP AND sb.BRANCH_CODE = inv.BRANCH_CODE WHERE inv.total_inv IS NULL OR inv.total_inv = 0 ), missing_branch_codes_final AS ( SELECT SKU_GROUP, COUNT(DISTINCT BRANCH_CODE) AS missing_branch_code_count, LISTAGG(BRANCH_CODE, \', \') AS missing_branch_codes FROM missing_branch_matrix GROUP BY SKU_GROUP ), size_sets_final AS ( SELECT SKU_GROUP, CASE WHEN s_units > 0 AND m_units > 0 AND l_units > 0 AND xl_units > 0 THEN LEAST( FLOOR(s_units / 2), FLOOR(m_units / 3), FLOOR(l_units / 3), FLOOR(xl_units / 2) ) ELSE 0 END AS size_set_count FROM wh ) SELECT o.SKU_GROUP, o.NEW_CATEGORY, o.STYLE, o.DESIGNS, o.COLLAR_NEW, o.MATERIAL_NEW, o.SLEEVE_TYPE, o.FIT, o.COLOR, o.SKU_CLASS, o.cluster_count, o.clusters_list, COALESCE(m.missing_clusters, \'\') AS missing_clusters, COALESCE(b.missing_branch_codes, \'\') AS missing_branch_codes, COALESCE(b.missing_branch_code_count, 0) AS missing_branch_code_count, o.offline_inventory, COALESCE(w.wh_inventory, 0) AS wh_inventory, COALESCE(w.xs_units, 0) AS xs_units, COALESCE(w.s_units, 0) AS s_units, COALESCE(w.m_units, 0) AS m_units, COALESCE(w.l_units, 0) AS l_units, COALESCE(w.xl_units, 0) AS xl_units, COALESCE(p.total_sales, 0) AS total_sales_30d, COALESCE(p.share, 0) AS share, COALESCE(p.cumulative_share, 0) AS cumulative_share, COALESCE(p.percentage_category, \'NA\') AS percentage_category, COALESCE(s.size_set_count, 0) AS size_set_count, CASE WHEN p.percentage_category IN (\'10%\', \'20%\', \'30%\', \'40%\', \'50%\') THEN CASE WHEN COALESCE(s.size_set_count, 0) >= COALESCE(b.missing_branch_code_count, 0) THEN \'Allocate all missing\' WHEN COALESCE(s.size_set_count, 0) > 5 THEN \'Dynamic allocation\' ELSE NULL END ELSE NULL END AS remarks FROM offline o LEFT JOIN wh w ON UPPER(TRIM(o.SKU_GROUP)) = UPPER(TRIM(w.SKU_GROUP)) LEFT JOIN size_sets_final s ON UPPER(TRIM(o.SKU_GROUP)) = UPPER(TRIM(s.SKU_GROUP)) LEFT JOIN pareto_tagged p ON UPPER(TRIM(o.SKU_GROUP)) = UPPER(TRIM(p.SKU_GROUP)) LEFT JOIN missing_clusters_final m ON UPPER(TRIM(o.SKU_GROUP)) = UPPER(TRIM(m.SKU_GROUP)) LEFT JOIN missing_branch_codes_final b ON UPPER(TRIM(o.SKU_GROUP)) = UPPER(TRIM(b.SKU_GROUP)) WHERE o.cluster_count > 0 AND o.offline_inventory > 0 ORDER BY share DESC; Create or replace table snitch_db.maplemonk.demand_of_v1 as With Rankna as ( WITH filtered_skus_all AS ( SELECT DISTINCT SKU_GROUP FROM snitch_db.maplemonk.GLOBAL_PARETO_V2 WHERE PERCENTAGE_CATEGORY IN (\'10%\', \'20%\', \'30%\') OR LOWER(STYLE) LIKE \'%core%\' ), filtered_skus_core_only AS ( SELECT DISTINCT SKU_GROUP FROM snitch_db.maplemonk.GLOBAL_PARETO_V2 WHERE LOWER(STYLE) LIKE \'%core%\' ), branch_inventory_raw_all AS ( SELECT BRANCH_CODE, SKU_GROUP, MAX(MARKETPLACE_MAPPED) AS MARKETPLACE_MAPPED, MAX(CUT_SIZE_WITH_JIT_FLAG) AS CUT_SIZE_WITH_JIT_FLAG, SUM(COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0)) AS total_inv FROM snitch_db.maplemonk.offline_master WHERE SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_all) AND COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) > 0 GROUP BY BRANCH_CODE, SKU_GROUP ), branch_inventory_raw_core AS ( SELECT BRANCH_CODE, SKU_GROUP, SUM(COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0)) AS core_inv FROM snitch_db.maplemonk.offline_master WHERE SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_core_only) AND COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) > 0 GROUP BY BRANCH_CODE, SKU_GROUP ), branch_inventory_summary AS ( SELECT allinv.BRANCH_CODE, MAX(allinv.MARKETPLACE_MAPPED) AS MARKETPLACE_MAPPED, SUM(allinv.total_inv) AS total_inventory, COUNT(DISTINCT CASE WHEN allinv.SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_core_only) THEN allinv.SKU_GROUP END) AS sku_group_count_with_stock, COUNT(DISTINCT CASE WHEN allinv.SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_core_only) AND LOWER(allinv.CUT_SIZE_WITH_JIT_FLAG) = \'no\' THEN allinv.SKU_GROUP END) AS full_size_sku_group_count FROM branch_inventory_raw_all allinv GROUP BY allinv.BRANCH_CODE ), core_inventory_summary AS ( SELECT BRANCH_CODE, SUM(core_inv) AS core_inventory_only FROM branch_inventory_raw_core GROUP BY BRANCH_CODE ), core_depth AS ( SELECT BRANCH_CODE, STORE_SIZE_GROUP, CALCULATED_DEPTH, TOTAL_UNITS, ADJUSTED_OPTION_COUNT FROM snitch_db.maplemonk.MDQ_V1 WHERE LOWER(STYLE_TYPE) = \'core\' ), allocate_all_summary AS ( SELECT TRIM(branch_code) AS BRANCH_CODE, COUNT(DISTINCT SKU_GROUP) AS allocate_all_missing_sku_group_count FROM ( SELECT SKU_GROUP, TRIM(SPLIT_PART(mbc.value::string, \',\', 1)) AS branch_code FROM snitch_db.maplemonk.GLOBAL_PARETO_V2, LATERAL FLATTEN(input => SPLIT(MISSING_BRANCH_CODES, \',\')) AS mbc WHERE REMARKS = \'Allocate all missing\'and BRANCH_CODE !=\'\' AND MISSING_BRANCH_CODES IS NOT NULL ) GROUP BY TRIM(branch_code) ), base_output AS ( SELECT b.BRANCH_CODE, b.MARKETPLACE_MAPPED, b.total_inventory, c.core_inventory_only, b.sku_group_count_with_stock, b.full_size_sku_group_count, d.STORE_SIZE_GROUP, d.CALCULATED_DEPTH, d.TOTAL_UNITS, d.ADJUSTED_OPTION_COUNT, (d.ADJUSTED_OPTION_COUNT - b.full_size_sku_group_count) AS delta_core_options_gap, COALESCE(a.allocate_all_missing_sku_group_count, 0) AS allocate_all_missing, GREATEST( (d.ADJUSTED_OPTION_COUNT - b.full_size_sku_group_count) - COALESCE(a.allocate_all_missing_sku_group_count, 0), 0 ) AS actual_delta FROM branch_inventory_summary b LEFT JOIN core_inventory_summary c ON b.BRANCH_CODE = c.BRANCH_CODE LEFT JOIN core_depth d ON b.BRANCH_CODE = d.BRANCH_CODE LEFT JOIN allocate_all_summary a ON b.BRANCH_CODE = a.BRANCH_CODE ), ranked_output AS ( SELECT *, CASE WHEN STORE_SIZE_GROUP = \'C\' THEN 1 WHEN STORE_SIZE_GROUP = \'B\' THEN 2 WHEN STORE_SIZE_GROUP = \'A\' THEN 3 ELSE 4 END AS store_priority FROM base_output ) SELECT *, CASE WHEN actual_delta > 0 THEN ROW_NUMBER() OVER ( ORDER BY CASE WHEN STORE_SIZE_GROUP = \'C\' THEN 1 WHEN STORE_SIZE_GROUP = \'B\' THEN 2 WHEN STORE_SIZE_GROUP = \'A\' THEN 3 ELSE 4 END, actual_delta DESC ) ELSE 9999 end as final_rank FROM ranked_output ORDER BY FINAL_RANK ) , meta as ( WITH sales_based_sku_sales AS ( SELECT BRANCH_CODE, SKU_GROUP, SUM(SALES_LAST_30_DAYS) AS total_sales FROM snitch_db.maplemonk.offline_master WHERE SALES_LAST_30_DAYS IS NOT NULL AND BRANCH_CODE IS NOT NULL AND SKU_GROUP IS NOT NULL AND COALESCE(NEW_CATEGORY, \'\') NOT IN (\'Sunglasses\', \'Perfumes\', \'Belts\', \'Shoes\', \'Bags\', \'\') GROUP BY BRANCH_CODE, SKU_GROUP ), sales_ranked AS ( SELECT *, 100 * DIV0(total_sales, SUM(total_sales) OVER (PARTITION BY BRANCH_CODE)) AS share FROM sales_based_sku_sales ), sales_pareto AS ( SELECT BRANCH_CODE, SKU_GROUP, SUM(share) OVER ( PARTITION BY BRANCH_CODE ORDER BY share DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_share FROM sales_ranked ), sales_pareto_tagged AS ( SELECT BRANCH_CODE, SKU_GROUP, CASE WHEN cumulative_share <= 10 THEN \'10%\' WHEN cumulative_share <= 20 THEN \'20%\' WHEN cumulative_share <= 30 THEN \'30%\' WHEN cumulative_share <= 40 THEN \'40%\' WHEN cumulative_share <= 50 THEN \'50%\' WHEN cumulative_share <= 60 THEN \'60%\' WHEN cumulative_share <= 70 THEN \'70%\' WHEN cumulative_share <= 80 THEN \'80%\' WHEN cumulative_share <= 90 THEN \'90%\' ELSE \'100%\' END AS pareto_category FROM sales_pareto ), non_fresh_sales_based AS ( SELECT BRANCH_CODE, SKU_GROUP, SUM(SALES_LAST_30_DAYS) AS total_sales FROM snitch_db.maplemonk.offline_master WHERE COALESCE(JIT_QTY, 0) + COALESCE(INVENTORY, 0) > 0 AND COALESCE(FRESH_INVENTORY, 0) = 0 AND BRANCH_CODE IS NOT NULL AND SKU_GROUP IS NOT NULL AND COALESCE(NEW_CATEGORY, \'\') NOT IN (\'Sunglasses\', \'Perfumes\', \'Belts\', \'Shoes\', \'Bags\', \'\') GROUP BY BRANCH_CODE, SKU_GROUP ), non_fresh_ranked AS ( SELECT *, 100 * DIV0(total_sales, SUM(total_sales) OVER (PARTITION BY BRANCH_CODE)) AS share FROM non_fresh_sales_based ), non_fresh_pareto AS ( SELECT BRANCH_CODE, SKU_GROUP, SUM(share) OVER ( PARTITION BY BRANCH_CODE ORDER BY share DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_share FROM non_fresh_ranked ), inventory_pareto_tagged AS ( SELECT BRANCH_CODE, SKU_GROUP, CASE WHEN cumulative_share <= 10 THEN \'10%\' WHEN cumulative_share <= 20 THEN \'20%\' WHEN cumulative_share <= 30 THEN \'30%\' WHEN cumulative_share <= 40 THEN \'40%\' WHEN cumulative_share <= 50 THEN \'50%\' WHEN cumulative_share <= 60 THEN \'60%\' WHEN cumulative_share <= 70 THEN \'70%\' WHEN cumulative_share <= 80 THEN \'80%\' WHEN cumulative_share <= 90 THEN \'90%\' ELSE \'100%\' END AS non_fresh_pareto_category FROM non_fresh_pareto ), final AS ( SELECT f.BRANCH_CODE, f.MARKETPLACE_MAPPED, f.NEW_CATEGORY AS CATEGORY, f.SKU_GROUP, f.STYLE, f.DESIGNS, f.COLLAR_NEW, f.MATERIAL_NEW, f.SLEEVE_TYPE, f.FIT, f.COLOR, f.SKU_CLASS, SUM(f.JIT_QTY + f.INVENTORY) AS TTL_QTY, MAX(f.FRESH_INVENTORY) AS FRESH_INVENTORY, spt.pareto_category, CASE WHEN MAX(f.FRESH_INVENTORY) = 0 THEN ipt.non_fresh_pareto_category ELSE NULL END AS non_fresh_pareto_category FROM snitch_db.maplemonk.offline_master f LEFT JOIN sales_pareto_tagged spt ON f.BRANCH_CODE = spt.BRANCH_CODE AND f.SKU_GROUP = spt.SKU_GROUP LEFT JOIN inventory_pareto_tagged ipt ON f.BRANCH_CODE = ipt.BRANCH_CODE AND f.SKU_GROUP = ipt.SKU_GROUP WHERE f.BRANCH_CODE IS NOT NULL AND f.SKU_GROUP IS NOT NULL AND f.NEW_CATEGORY IS NOT NULL AND f.NEW_CATEGORY NOT IN (\'Sunglasses\', \'Perfumes\', \'Belts\', \'Shoes\', \'Bags\', \'\') AND f.INVENTORY + f.JIT_QTY > 0 GROUP BY f.BRANCH_CODE, f.MARKETPLACE_MAPPED, f.NEW_CATEGORY, f.SKU_GROUP, f.STYLE, f.DESIGNS, f.COLLAR_NEW, f.MATERIAL_NEW, f.SLEEVE_TYPE, f.FIT, f.COLOR, f.SKU_CLASS, spt.pareto_category, ipt.non_fresh_pareto_category ), filtered_combos AS ( SELECT * FROM final WHERE pareto_category IN (\'10%\', \'20%\', \'30%\') AND CATEGORY IN (\'Shirts\', \'T-Shirts\', \'Jeans\', \'Trousers\', \'Cargo Pants\', \'Shorts\') ), combo_keys AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, CATEGORY, CASE WHEN CATEGORY = \'Shirts\' THEN COALESCE(DESIGNS, \'NA\') || \' + \' || COALESCE(FIT, \'NA\') || \' + \' || COALESCE(MATERIAL_NEW, \'NA\') WHEN CATEGORY = \'T-Shirts\' THEN COALESCE(COLLAR_NEW, \'NA\') || \' + \' || COALESCE(DESIGNS, \'NA\') || \' + \' || COALESCE(FIT, \'NA\') WHEN CATEGORY = \'Jeans\' THEN COALESCE(FIT, \'NA\') || \' + \' || COALESCE(DESIGNS, \'NA\') WHEN CATEGORY IN (\'Trousers\', \'Cargo Pants\', \'Shorts\') THEN COALESCE(CATEGORY, \'NA\') || \' + \' || COALESCE(DESIGNS, \'NA\') END AS METAFIELD_COMBINATION FROM filtered_combos ), combo_counts AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, CATEGORY, METAFIELD_COMBINATION, COUNT(*) AS OCCURRENCE_COUNT FROM combo_keys GROUP BY BRANCH_CODE, MARKETPLACE_MAPPED, CATEGORY, METAFIELD_COMBINATION ), ranked_combos AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY BRANCH_CODE, CATEGORY ORDER BY OCCURRENCE_COUNT DESC ) AS RANK FROM combo_counts ) SELECT BRANCH_CODE, MARKETPLACE_MAPPED, CATEGORY, METAFIELD_COMBINATION, OCCURRENCE_COUNT, RANK FROM ranked_combos WHERE (CATEGORY = \'Jeans\' AND RANK <= 5) OR (CATEGORY = \'Cargo Pants\' AND RANK = 1)OR (CATEGORY = \'Shirts\' AND RANK <= 5)OR (CATEGORY = \'T-Shirts\' AND RANK <= 5)OR (CATEGORY = \'Trousers\' AND RANK = 1) OR (CATEGORY = \'Shorts\' AND RANK = 1) ORDER BY BRANCH_CODE, CATEGORY, RANK ) Select a.*, b.final_rank, SPLIT(a.METAFIELD_COMBINATION, \' + \') AS demand_keywords from meta a left join rankna b on trim(a.branch_code) = trim(b.branch_code) order by final_rank asc; CREATE or replace table snitch_db.maplemonk.MDQ_V2 AS WITH filtered_skus_all AS ( SELECT DISTINCT SKU_GROUP FROM snitch_db.maplemonk.GLOBAL_PARETO_V2 WHERE PERCENTAGE_CATEGORY IN (\'10%\', \'20%\', \'30%\') OR LOWER(STYLE) LIKE \'%core%\' ), filtered_skus_core_only AS ( SELECT DISTINCT SKU_GROUP FROM snitch_db.maplemonk.GLOBAL_PARETO_V2 WHERE LOWER(STYLE) LIKE \'%core%\' ), branch_inventory_raw_all AS ( SELECT BRANCH_CODE, SKU_GROUP, MAX(MARKETPLACE_MAPPED) AS MARKETPLACE_MAPPED, MAX(CUT_SIZE_WITH_JIT_FLAG) AS CUT_SIZE_WITH_JIT_FLAG, SUM(COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0)) AS total_inv FROM snitch_db.maplemonk.offline_master WHERE SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_all) AND COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) > 0 GROUP BY BRANCH_CODE, SKU_GROUP ), branch_inventory_raw_core AS ( SELECT BRANCH_CODE, SKU_GROUP, SUM(COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0)) AS core_inv FROM snitch_db.maplemonk.offline_master WHERE SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_core_only) AND COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) > 0 and branch_code is not null GROUP BY BRANCH_CODE, SKU_GROUP ), branch_inventory_summary AS ( SELECT allinv.BRANCH_CODE, MAX(allinv.MARKETPLACE_MAPPED) AS MARKETPLACE_MAPPED, SUM(allinv.total_inv) AS total_inventory, COUNT(DISTINCT CASE WHEN allinv.SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_core_only) THEN allinv.SKU_GROUP END) AS sku_group_count_with_stock, COUNT(DISTINCT CASE WHEN allinv.SKU_GROUP IN (SELECT SKU_GROUP FROM filtered_skus_core_only) AND LOWER(allinv.CUT_SIZE_WITH_JIT_FLAG) = \'no\' THEN allinv.SKU_GROUP END) AS full_size_sku_group_count FROM branch_inventory_raw_all allinv GROUP BY allinv.BRANCH_CODE ), core_inventory_summary AS ( SELECT BRANCH_CODE, SUM(core_inv) AS core_inventory_only FROM branch_inventory_raw_core GROUP BY BRANCH_CODE ), core_depth AS ( SELECT BRANCH_CODE, STORE_SIZE_GROUP, CALCULATED_DEPTH, TOTAL_UNITS, ADJUSTED_OPTION_COUNT FROM snitch_db.maplemonk.MDQ_V1 WHERE LOWER(STYLE_TYPE) = \'core\' ), allocate_all_summary AS ( SELECT TRIM(branch_code) AS BRANCH_CODE, COUNT(DISTINCT SKU_GROUP) AS allocate_all_missing_sku_group_count FROM ( SELECT SKU_GROUP, TRIM(SPLIT_PART(mbc.value::string, \',\', 1)) AS branch_code FROM snitch_db.maplemonk.GLOBAL_PARETO_V2, LATERAL FLATTEN(input => SPLIT(MISSING_BRANCH_CODES, \',\')) AS mbc WHERE REMARKS = \'Allocate all missing\' and BRANCH_CODE !=\'\' AND MISSING_BRANCH_CODES IS NOT NULL ) GROUP BY TRIM(branch_code) ), Dynamic_matching as (Select BRANCH_CODE, count (distinct sku_group) as Dynamic_Styles FROM ( WITH exploded_demand AS ( SELECT BRANCH_CODE, FINAL_RANK, METAFIELD_COMBINATION, CATEGORY, MARKETPLACE_MAPPED, demand_keywords FROM snitch_db.maplemonk.demand_of_v1 ), exploded_supply AS ( SELECT SKU_GROUP, METAFIELD_COMBINATION AS SKU_METAFIELD, SIZE_SET_COUNT, MISSING_BRANCH_CODES, SPLIT(METAFIELD_COMBINATION, \' + \') AS supply_keywords, NEW_CATEGORY AS SUPPLY_CATEGORY FROM ( SELECT sku_group, NEW_CATEGORY, CASE WHEN NEW_CATEGORY = \'Shirts\' THEN COALESCE(DESIGNS, \'NA\') || \' + \' || COALESCE(FIT, \'NA\') || \' + \' || COALESCE(MATERIAL_NEW, \'NA\') WHEN NEW_CATEGORY = \'T-Shirts\' THEN COALESCE(COLLAR_NEW, \'NA\') || \' + \' || COALESCE(DESIGNS, \'NA\') || \' + \' || COALESCE(FIT, \'NA\') WHEN NEW_CATEGORY = \'Jeans\' THEN COALESCE(FIT, \'NA\') || \' + \' || COALESCE(DESIGNS, \'NA\') WHEN NEW_CATEGORY IN (\'Trousers\', \'Cargo Pants\', \'Shorts\') THEN COALESCE(NEW_CATEGORY, \'NA\') || \' + \' || COALESCE(DESIGNS, \'NA\') END AS METAFIELD_COMBINATION, missing_branch_codes, missing_branch_code_count, size_set_count FROM snitch_db.maplemonk.GLOBAL_PARETO_V2 WHERE remarks = \'Dynamic allocation\' ORDER BY CUMULATIVE_SHARE ASC ) ), supply_branches AS ( SELECT SKU_GROUP, SKU_METAFIELD, SIZE_SET_COUNT, TRIM(f.value::STRING) AS BRANCH_CODE, supply_keywords, SUPPLY_CATEGORY FROM exploded_supply, LATERAL FLATTEN(INPUT => SPLIT(MISSING_BRANCH_CODES, \',\')) f ), matched AS ( SELECT s.SKU_GROUP, s.SKU_METAFIELD, s.BRANCH_CODE, d.METAFIELD_COMBINATION AS BRANCH_METAFIELD, d.FINAL_RANK, ARRAY_SIZE(ARRAY_INTERSECTION(s.supply_keywords, d.demand_keywords)) AS MATCH_SCORE, s.SUPPLY_CATEGORY, d.CATEGORY AS DEMAND_CATEGORY FROM supply_branches s JOIN exploded_demand d ON s.BRANCH_CODE = d.BRANCH_CODE AND s.SUPPLY_CATEGORY = d.CATEGORY ), deduped_matches AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY SKU_GROUP, BRANCH_CODE ORDER BY FINAL_RANK ASC, MATCH_SCORE DESC ) AS rn_dedup FROM matched ), ranked_matches AS ( SELECT d.*, p2.CUMULATIVE_SHARE, ROW_NUMBER() OVER ( PARTITION BY d.BRANCH_CODE ORDER BY p2.CUMULATIVE_SHARE ASC ) AS rn_by_branch FROM deduped_matches d JOIN snitch_db.maplemonk.GLOBAL_PARETO_V2 p2 ON d.SKU_GROUP = p2.SKU_GROUP WHERE d.rn_dedup = 1 ), final_allocations AS ( SELECT r.SKU_GROUP, r.BRANCH_CODE, r.MATCH_SCORE, r.FINAL_RANK, r.rn_by_branch, p.SIZE_SET_COUNT, r.SUPPLY_CATEGORY, r.DEMAND_CATEGORY, r.BRANCH_METAFIELD, r.SKU_METAFIELD, m.Actual_DELTA FROM ranked_matches r JOIN snitch_db.maplemonk.GLOBAL_PARETO_V2 p ON r.SKU_GROUP = p.SKU_GROUP JOIN SNITCH_DB.MAPLEMONK.MDQ_V2 m ON r.BRANCH_CODE = m.BRANCH_CODE ) SELECT SKU_GROUP, BRANCH_CODE, SUPPLY_CATEGORY AS CATEGORY, SKU_METAFIELD AS SUPPLY_METAFIELD, BRANCH_METAFIELD AS DEMAND_METAFIELD, MATCH_SCORE, FINAL_RANK, CASE WHEN rn_by_branch <= ACTUAL_DELTA AND FINAL_RANK < 999 THEN \'YES\' ELSE \'NO\' END AS IS_ELIGIBLE FROM final_allocations ORDER BY BRANCH_CODE, FINAL_RANK ) where IS_ELIGIBLE = \'YES\' GROUP BY 1), base_output AS ( SELECT b.BRANCH_CODE, b.MARKETPLACE_MAPPED, b.total_inventory, c.core_inventory_only, b.sku_group_count_with_stock, b.full_size_sku_group_count, d.STORE_SIZE_GROUP, d.CALCULATED_DEPTH, d.TOTAL_UNITS, d.ADJUSTED_OPTION_COUNT, (d.ADJUSTED_OPTION_COUNT - b.full_size_sku_group_count) AS delta_core_options_gap, COALESCE(a.allocate_all_missing_sku_group_count, 0) AS allocate_all_missing, GREATEST( (d.ADJUSTED_OPTION_COUNT - b.full_size_sku_group_count) - COALESCE(a.allocate_all_missing_sku_group_count, 0), 0 ) AS actual_delta, COALESCE(g.Dynamic_Styles, 0) AS Dynamic_Styles, GREATEST( (d.ADJUSTED_OPTION_COUNT - b.full_size_sku_group_count) - COALESCE(a.allocate_all_missing_sku_group_count, 0), 0 ) - COALESCE(g.Dynamic_Styles, 0) as new_delta FROM branch_inventory_summary b LEFT JOIN core_inventory_summary c ON b.BRANCH_CODE = c.BRANCH_CODE LEFT JOIN core_depth d ON b.BRANCH_CODE = d.BRANCH_CODE LEFT JOIN allocate_all_summary a ON b.BRANCH_CODE = a.BRANCH_CODE left join Dynamic_matching g on b.BRANCH_CODE = g.BRANCH_CODE ), ranked_output AS ( SELECT *, CASE WHEN STORE_SIZE_GROUP = \'C\' THEN 1 WHEN STORE_SIZE_GROUP = \'B\' THEN 2 WHEN STORE_SIZE_GROUP = \'A\' THEN 3 ELSE 4 END AS store_priority FROM base_output ), final_output AS ( SELECT *, CASE WHEN actual_delta > 0 THEN ROW_NUMBER() OVER ( ORDER BY CASE WHEN STORE_SIZE_GROUP = \'C\' THEN 1 WHEN STORE_SIZE_GROUP = \'B\' THEN 2 WHEN STORE_SIZE_GROUP = \'A\' THEN 3 ELSE 4 END, actual_delta DESC ) ELSE NULL END AS FINAL_RANK FROM ranked_output ) SELECT * FROM final_output ORDER BY CASE WHEN FINAL_RANK IS NOT NULL THEN FINAL_RANK ELSE 999999 END; CREATE or replace table snitch_db.maplemonk.Sellthrorughoffline as Select * from ( Select a.*, b.product_type from ( With last_30 as ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'6XL\', XL6_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 ), NEXT30D_STR AS ( SELECT I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE AS SNAPSHOT_DATE, I.INVENTORY AS OPENING_INVENTORY, COALESCE(SUM(S.SHIPPING_QUANTITY), 0) AS NEXT_30_DAYS_SALES FROM INVENTORY_UNPVT I LEFT JOIN snitch_db.maplemonk.Store_Fact_items_offline S ON S.BRANCH_CODE = I.BRANCH_CODE AND UPPER(S.SKU_GROUP) = I.SKU_GROUP AND CASE WHEN S.SIZE = \'XXXL\' THEN \'3XL\' WHEN S.SIZE = \'XXL\' THEN \'XXL\' WHEN S.SIZE = \'XS\' THEN \'XS\' WHEN S.SIZE = \'XL\' THEN \'XL\' WHEN S.SIZE = \'S\' THEN \'S\' WHEN S.SIZE = \'M\' THEN \'M\' WHEN S.SIZE = \'L\' THEN \'L\' WHEN S.SIZE = \'6XL\' THEN \'6XL\' WHEN S.SIZE = \'5XL\' THEN \'5XL\' WHEN S.SIZE = \'4XL\' THEN \'4XL\' WHEN S.SIZE = \'3XL\' THEN \'3XL\' WHEN S.SIZE = \'2XL\' THEN \'XXL\' WHEN S.SIZE = \'06XL\' THEN \'6XL\' WHEN S.SIZE = \'01XL\' THEN \'XL\' WHEN S.SIZE = \'46\' THEN \'6XL\' WHEN S.SIZE = \'44\' THEN \'5XL\' WHEN S.SIZE = \'42\' THEN \'5XL\' WHEN S.SIZE = \'40\' THEN \'3XL\' WHEN S.SIZE = \'38\' THEN \'XXL\' WHEN S.SIZE = \'36\' THEN \'XL\' WHEN S.SIZE = \'34\' THEN \'L\' WHEN S.SIZE = \'32\' THEN \'M\' WHEN S.SIZE = \'30\' THEN \'S\' WHEN S.SIZE = \'28\' THEN \'XS\' ELSE \'NO_MATCH\' END = I.SIZE AND S.ORDER_DATE > I.DATE AND S.ORDER_DATE <= LEAST(DATEADD(DAY, 30, I.DATE), CURRENT_DATE) GROUP BY I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE, I.INVENTORY ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, SNAPSHOT_DATE AS DATE, OPENING_INVENTORY, NEXT_30_DAYS_SALES, LEAST(NEXT_30_DAYS_SALES, OPENING_INVENTORY) AS SALES_CONSIDERED FROM NEXT30D_STR WHERE SNAPSHOT_DATE = current_date -30 ORDER BY SNAPSHOT_DATE, BRANCH_CODE, SKU_GROUP, SIZE, MARKETPLACE_MAPPED ), last_45 as ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, DATE